import itertools, json
jobs='ABCDE'
slot=dict(zip(jobs,[[0,1,4,11,3],[2,3,3,2,5],[4,8,2,10,8],[3,2,11,3,4],[10,6,10,10,4]]))
trans=dict(zip(jobs,[dict(zip(jobs,r)) for r in [[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(trans[a][b] for a,b in zip(p,p[1:]))
def incident(p,k):
 pos={j:p.index(j)+1 for j in jobs}
 if pos['A']>=pos['D']: return None
 if k=='rain':
  if pos['D']==1 or pos['A']==1:return None
  penalty=6*max(0,pos['C']-1)
 elif k=='road':
  if pos['C']==4 or pos['E']==2:return None
  penalty=6*max(0,pos['D']-3)
 else:
  if pos['A']==1 or pos['B']==1:return None
  penalty=10*max(0,pos['E']-2)
 return nominal(p)+penalty
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'):continue
 candidates=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i]
  candidates.append((tuple(q),1))
 repairs={};costs={}
 for k in ['rain','road','lift']:
  legal=[(incident(q,k)+fee,''.join(q)) for q,fee in candidates if incident(q,k) is not None]
  if not legal:break
  costs[k],repairs[k]=min(legal)
 else:
  results.append((nominal(p)+max(costs.values()),''.join(p),repairs,costs))
results.sort()
best=results[0]
print(json.dumps(dict(roster=best[1],score=best[0],repairs=best[2],repair_costs=best[3],feasible_count=len(results),next_score=min(r[0] for r in results if r[0]>best[0]))))
print('best nominal',nominal(tuple(best[1])))
print('optima',[(x[1],x[0]) for x in results if x[0]==best[0]])

